'use strict';
window.TuriWorkspace=(()=>{
 let ctx,store={},integrations=[],adminData=null,page='home',owner='',search='',notice='',busy=false,pendingProducer=null;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={active:'Activa',renewal:'En renovación',cancelled:'Baja registrada',expired:'Vencida',reported:'Denunciado',documents:'Falta documentación',insurer:'Espera aseguradora',resolved:'Resuelto',open:'Pendiente',done:'Resuelta',draft:'Borrador',requested:'Pedido registrado',comparing:'Comparando',approval:'Para revisar',approved:'Revisión PAS aprobada',rejected:'Cerrada sin avanzar',red:'Alta',amber:'Media',green:'Baja',unknown:'Sin verificar',current:'Al día',pending:'Pendiente',confirmed:'Confirmado',blocked:'Bloqueado',assisted:'Gestión asistida',api_requested:'API en evaluación',documentation:'Documentación recibida',testing:'Prueba pendiente de resultado',monthly:'Mensual',annual:'Anual',single:'Pago único',renewals:'Renovaciones',updates:'Actualizaciones',requotes:'Recotizaciones',cancellations:'Bajas',claims:'Siniestros',payments:'Pagos',accounting:'Contabilidad',marketing:'Marketing y ventas',other:'Otra gestión'};
 const branches=['Autos','Motos','Hogar','Comercio','Caución','Accidentes personales','Responsabilidad civil','Vida','Salud','ART','Transporte','Otros'];
 const titles={emission:'Formularios y emisión.',multiquote:'Cotizá con Turi.',home:'Tu día, más simple.',clients:'Tus clientes.',policies:'Tu cartera, en orden.',claims:'Cada siniestro, al día.',quotes:'Del pedido a la propuesta.',tasks:'Todo lo que sigue.',companies:'Tus compañías, juntas.',producers:'El equipo Turi.',archive:'Históricos recuperables.',activity:'Cada paso, registrado.',documents:'Tus documentos, a mano.'};
 const sub={emission:'Datos del cliente, revisión del PAS y seguimiento del cobro.',multiquote:'Empezá con lo que sabés. Afiná cuando tengas más información.',home:'Prioridades y próximos pasos de tu operación.',clients:'Datos de contacto, contexto y próximas oportunidades.',policies:'Registrá y seguí pólizas existentes. Los cambios deben confirmarse en la compañía.',claims:'Un expediente y un próximo paso para cada caso.',quotes:'Un pedido, varias propuestas y la revisión del productor.',tasks:'Renovaciones, administración, contabilidad y ventas en una sola agenda.',companies:'Códigos propios y avance de cada integración.',producers:'Supervisión de cuentas, acceso y preparación de los productores.',archive:'Registros retirados del tablero, con nota y posibilidad de restaurar.',activity:'Actividad registrada en el servidor, sin exponer códigos ni contraseñas.',documents:'PDF y fotos organizados por cliente, con el archivo original siempre disponible.'};
 const icons={archive:'M3 6h18M5 6v15h14V6M3 3h18v3H3z M9 11h6',emission:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',home:'M3 10l9-7 9 7v10H3z M9 20v-8h6v8',clients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-2a4 4 0 0 0-3-3.87 M16 3a4 4 0 0 1 0 8',policies:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h5',claims:'M12 3l9 4v5c0 5-9 9-9 9S3 17 3 12V7z M12 8v5 M12 17h.01',quotes:'M4 4h16v12H8l-4 4z M8 8h8 M8 12h5',tasks:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 12l2 2 5-5 M8 18h8',companies:'M3 21h18 M5 21V7h14v14 M3 7l9-4 9 4 M9 11v6 M15 11v6',producers:'M4 21v-3a5 5 0 0 1 10 0v3 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 11l2 2 3-3 M17 18h5',activity:'M3 12h4l3-8 4 16 3-8h4',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',close:'M6 6l12 12 M6 18L18 6',check:'M5 12l4 4L19 6'};
 const icon=k=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[k]||icons.policies}"/></svg>`;
 const admin=()=>ctx.user.role==='superadmin',name=id=>store.owners?.find(u=>u.id===id)?.name||'Cuenta',company=id=>ctx.companies.find(c=>c.id===id)?.name||id;
 const byId=(type,id)=>store[type]?.find(r=>r.id===id);
 const clientName=id=>byId('clients',id)?.name||'Sin cliente',policyName=id=>{const p=byId('policies',id);return p?`${p.number} · ${clientName(p.client_id)}`:'Sin póliza'};
 const date=v=>v?new Date(v+(String(v).length===10?'T12:00:00Z':'')).toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'numeric'}):'Sin fecha';
 const money=(v,c='ARS')=>new Intl.NumberFormat('es-AR',{style:'currency',currency:c,maximumFractionDigits:2}).format((v||0)/100);
 const days=v=>Math.round((Date.parse(v+'T12:00:00Z')-Date.parse(store.today+'T12:00:00Z'))/86400000);
 const pill=(text,tone='neutral')=>`<span class="w-badge ${tone}">${esc(text)}</span>`;
 const status=s=>pill(labels[s]||s,['approved','done','resolved','current','confirmed'].includes(s)?'good':['cancelled','expired','blocked'].includes(s)?'danger':['renewal','approval','documents','pending','requested'].includes(s)?'warn':'neutral');
 const btn=(text,action,extra='',primary=false)=>`<button class="${primary?'primary':''}" data-work="${action}" ${extra}>${esc(text)}</button>`;
 const owns=r=>(!owner||r.owner_id===owner)&&!r.archive;
 const rows=type=>(store[type]||[]).filter(owns).filter(r=>!search||[r.name,r.title,r.number,r.risk,r.reference,r.notes,clientName(r.client_id),r.company_id?company(r.company_id):'',r.branch,labels[r.status]].join(' ').toLowerCase().includes(search.toLowerCase()));
 const rowOwner=r=>admin()?`<span class="w-subtle">${esc(name(r.owner_id))}</span>`:'';
 const empty=(title,body,action,text)=>`<div class="w-empty">${icon(page)}<h3>${esc(title)}</h3><p>${esc(body)}</p>${action?btn(text,'new',`data-type="${action}"`,true):''}</div>`;
 const table=(heads,body)=>`<div class="scroll"><table class="table w-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
 function render(){
  document.body.classList.add('in-workspace');const menus=[['home','Mi día'],['clients','Clientes'],['policies','Pólizas'],['claims','Siniestros'],['quotes','Cotizaciones'],['multiquote','Multicotizador'],['emission','Formularios y emisión'],['tasks','Agenda y administración'],['documents','Documentos'],['companies','Compañías'],...(admin()?[['producers','Productores']]:[]),['archive','Históricos'],['activity','Actividad']];
  const actionType={clients:'clients',policies:'policies',claims:'claims',tasks:'tasks'}[page];
  ctx.root.innerHTML=`<aside class="w-sidebar"><a class="w-logo" href="/privado/" aria-label="Turi Gestión"><img src="/assets/logo.png" alt="Turi"><span>GESTIÓN</span></a><div class="w-space-label">TU ESPACIO DE TRABAJO</div><nav aria-label="Gestión">${menus.map(([id,label])=>`<button data-work="nav" data-page="${id}" class="${page===id?'selected':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='tasks'&&store.tasks?.filter(t=>owns(t)&&t.status==='open').length?`<span class="w-count">${store.tasks.filter(t=>owns(t)&&t.status==='open').length}</span>`:''}</button>`).join('')}</nav><div class="w-sidebar-bottom"><a href="https://wa.me/5491130216824" target="_blank" rel="noopener noreferrer">Un experto te acompaña ↗</a><div class="w-profile">${ctx.user.username==='dani'?'<img src="/assets/daniel.webp" alt="Daniel Stern">':`<span class="w-avatar">${esc(ctx.user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span>`}<div><b>${esc(ctx.user.name)}</b><small>${admin()?'Superadministrador':'Productor asesor'}</small></div></div><div class="w-account-links"><button data-action="email-settings">Mi correo</button><button data-action="logout">Salir</button></div></div></aside><div class="w-content"><header class="w-topbar"><span>TURI <span class="w-slash">/</span> ${esc(menus.find(m=>m[0]===page)?.[1]||'Gestión')}</span><div class="row"><div id="w-notification-slot"></div><span class="w-live-dot"></span><span class="small">Espacio privado</span><button class="w-refresh" data-work="refresh" aria-label="Actualizar datos">↻</button></div></header><div class="w-page"><div class="w-page-heading"><div><div class="eyebrow">${admin()?'SUPERVISIÓN Y OPERACIÓN':'HACELO SIMPLE, HACELO TURI'}</div><h1 tabindex="-1">${titles[page]}</h1><p>${sub[page]}</p></div>${actionType?btn('＋ '+({clients:'Nuevo cliente',policies:'Registrar póliza',claims:'Abrir siniestro',quotes:'Nueva solicitud',tasks:'Nueva tarea'}[page]),'new',`data-type="${actionType}"`,true):page==='quotes'?'<button class="primary" data-work="nav" data-page="multiquote">＋ Nueva solicitud</button>':page==='documents'?'<button class="primary" data-doc="upload">＋ Subir PDF o fotos</button>':page==='producers'&&admin()?'<div class="row"><button class="primary" data-work="invite-producer">＋ Invitar PAS</button><button data-work="new-producer">Crear PAS de prueba</button></div>':page==='companies'&&!admin()?'<button class="primary" data-action="add">＋ Agregar compañía</button>':''}</div><div id="error" class="error" role="alert"></div>${ctx.emailRecoveryAvailable&&!ctx.user.emailVerified?'<div class="hint warning row between"><span>Confirmá tu correo para recuperar tu acceso automáticamente.</span><button data-action="email-settings">Confirmar mi correo</button></div>':''}${notice?`<div class="w-notice" role="status">${icon('check')}<span>${esc(notice)}</span><button data-work="dismiss" aria-label="Cerrar aviso">×</button></div>`:''}${page!=='emission'&&page!=='multiquote'&&page!=='documents'&&page!=='activity'&&page!=='producers'&&(page!=='home'||admin())?filters():''}<div id="w-body">${content()}</div></div><footer class="w-footer"><span>Menos vueltas. Más tiempo para tus clientes.</span><span>Turi Gestión · Piloto en desarrollo</span></footer></div><div id="w-dialog-slot"></div>`;window.TuriNotifications?.mount();
 }
 function filters(){return `<div class="w-filters">${admin()?`<label class="w-filter-owner">Cartera<select id="work-owner"><option value="">Toda la organización</option>${(store.owners||[]).map(u=>`<option value="${esc(u.id)}" ${owner===u.id?'selected':''}>${esc(u.name)}${u.id===ctx.user.id?' · mi espacio':''}</option>`).join('')}</select></label>`:''}${page!=='home'?`<label class="w-search">${icon('search')}<input id="work-search" placeholder="Buscar en esta sección" value="${esc(search)}" aria-label="Buscar en esta sección"></label>`:''}<span class="small">Guardado en tu cuenta</span></div>`}
 function content(){switch(page){case'emission':return window.TuriEmission?.render()||'';case'multiquote':return window.TuriMultiQuote?.render()||'';case'home':return home();case'clients':return clientsPage();case'policies':return policiesPage();case'claims':return claimsPage();case'quotes':return quotesPage();case'tasks':return tasksPage();case'companies':return companiesPage();case'producers':return producersPage();case'archive':return archivePage();case'activity':return activityPage();case'documents':return window.TuriDocuments?.render()||'';default:return ''}}
 function home(){
  const tasks=(store.tasks||[]).filter(t=>owns(t)&&t.status==='open').sort((a,b)=>a.due_on.localeCompare(b.due_on)||(['red','amber','green'].indexOf(a.priority)-['red','amber','green'].indexOf(b.priority)));
  const renewals=(store.policies||[]).filter(p=>owns(p)&&['active','renewal'].includes(p.status)&&days(p.expires_on)<=30).sort((a,b)=>a.expires_on.localeCompare(b.expires_on));
  const claims=(store.claims||[]).filter(c=>owns(c)&&c.status!=='resolved');const quotes=[...(store.quotes||[]).filter(q=>owns(q)&&!['approved','rejected'].includes(q.status)),...(store.quoteIntakes||[]).filter(owns)];
  const priorities=[...tasks.map(t=>({...t,kind:'tasks',due:t.due_on,area:labels[t.category]})),...claims.filter(c=>c.next_due&&days(c.next_due)<=7).map(c=>({...c,kind:'claims',due:c.next_due,priority:days(c.next_due)<0?'red':'amber',area:'Seguimiento de siniestro'})),...(store.policies||[]).filter(p=>owns(p)&&['active','renewal'].includes(p.status)&&p.paymentStatus==='pending').map(p=>({...p,kind:'policies',due:store.today,title:'Revisar pago · '+clientName(p.client_id),priority:'red',area:'Pago registrado como pendiente'}))].sort((a,b)=>a.due.localeCompare(b.due)||(['red','amber','green'].indexOf(a.priority)-['red','amber','green'].indexOf(b.priority)));
  const counts=[['Pólizas en cartera',(store.policies||[]).filter(p=>owns(p)&&['active','renewal'].includes(p.status)).length,'policies'],['Tareas pendientes',tasks.length,'tasks'],['Siniestros abiertos',claims.length,'claims'],['Solicitudes en curso',quotes.length,'quotes']];
  return `<section class="w-greeting"><div><div class="eyebrow">${esc(new Date().toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Argentina/Buenos_Aires'}))}</div><h2>Hola, ${esc(ctx.user.name.split(' ')[0])}.</h2><p>Todo lo importante, en un solo lugar.</p><div class="row">${btn('＋ Nuevo cliente','new','data-type="clients"',true)}${btn('Crear tarea','new','data-type="tasks"')}${!admin()?'<button data-action="add">Agregar compañía</button>':''}</div></div><img src="/assets/agente-turi.webp" alt="Asistente Turi" class="w-agent"><div class="w-greeting-tag">Tu criterio.<br>La tecnología de tu lado.</div></section><div class="w-stats">${counts.map(([label,n,dest])=>`<button data-work="nav" data-page="${dest}" class="w-stat"><span>${label}</span><strong>${n}</strong><small>Ver detalle ${icon('arrow')}</small></button>`).join('')}</div><div class="w-home-grid"><section class="panel"><div class="w-card-title"><h2>Primero, lo importante.</h2>${btn('Ver agenda','nav','data-page="tasks"')}</div>${priorities.length?priorities.slice(0,6).map(t=>`<div class="w-task-row"><span class="w-priority ${t.priority}" aria-label="Prioridad ${labels[t.priority]}"></span><div><b>${esc(t.title)}</b><small>${esc(t.area)} · ${date(t.due)}${days(t.due)<0?' · Vencida':''}</small>${rowOwner(t)}</div>${t.kind==='tasks'?`<button data-work="done" data-id="${t.id}" aria-label="Marcar resuelta: ${esc(t.title)}">${icon('check')}</button>`:`<button data-work="edit" data-type="${t.kind}" data-id="${t.id}" aria-label="Abrir: ${esc(t.title)}">${icon('arrow')}</button>`}</div>`).join(''):empty('Tu agenda empieza acá.','Registrá un próximo paso y Turi lo tendrá presente.','tasks','Crear mi primera tarea')}<div class="w-card-foot">Alertas de tus registros y fechas. Los avisos de las compañías aún no se sincronizan.</div></section><section class="panel"><div class="w-card-title"><h2>Renovaciones.</h2>${pill('Próximos 30 días')}</div>${renewals.length?renewals.slice(0,5).map(p=>`<button class="w-renewal" data-work="edit" data-type="policies" data-id="${p.id}"><div><b>${esc(clientName(p.client_id))}</b><small>${esc(p.risk)}</small></div>${pill(days(p.expires_on)<0?'Vencimiento pasado':days(p.expires_on)===0?'Hoy':`En ${days(p.expires_on)} días`,days(p.expires_on)<=3?'danger':'warn')}</button>`).join(''):empty('Sin vencimientos cercanos.','Las fechas de las pólizas que registres aparecerán aquí.','policies','Registrar una póliza')}</section></div><section class="panel w-start"><div><div class="eyebrow">DE LA DEMO A TU OPERACIÓN</div><h2>Preparemos el primer caso real.</h2><p>Los registros de este espacio se guardan en la base. Empezamos sin importar datos ficticios.</p></div><div class="w-checklist">${[['clients','1. Cargar un cliente',store.clients?.length],['companies','2. Registrar y relevar compañías',integrations.length],['quotes','3. Abrir una solicitud',(store.quotes?.length||0)+(store.quoteIntakes?.length||0)],['tasks','4. Agendar el seguimiento',store.tasks?.length]].map(([dest,title,n])=>`<button data-work="nav" data-page="${dest}"><span class="w-check ${n?'checked':''}">${n?'✓':'○'}</span>${title}${icon('arrow')}</button>`).join('')}</div></section>`;
 }

 function archiveButton(type,r,label){return '<button type="button" class="w-trash" data-work="archive" data-type="'+type+'" data-id="'+esc(r.id)+'" aria-label="Enviar a Históricos: '+esc(label)+'" title="Enviar a Históricos"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button>';}
 function archivePage(){const records=(store.archiveRecords||[]).filter(r=>(!owner||r.owner_id===owner)&&(!search||[r.label,r.note,archiveLabels[r.type]].join(' ').toLowerCase().includes(search.toLowerCase())));return '<div class="w-inline-note">Históricos conserva una copia del registro, la nota y su atribución. Los documentos y registros vinculados siguen guardados. Archivar una póliza no solicita su baja a la aseguradora. La limpieza definitiva queda pendiente de una revisión y autorización; no hay borrado automático.</div><section class="panel w-list-panel">'+(records.length?table(['Registro','Nota y fecha','Resguardo',''],records.map(r=>'<tr><td><b>'+esc(r.label)+'</b><span class="w-subtle">'+esc(archiveLabels[r.type]||r.type)+'</span>'+rowOwner(r)+'</td><td>'+esc(r.note||'Sin nota')+'<span class="w-subtle">'+esc(new Date(r.archivedAt).toLocaleString('es-AR'))+'</span></td><td>'+pill('Recuperable','good')+(r.type==='clients'?'<span class="w-subtle">'+(r.marketingConsent?'Acepta comunicaciones comerciales':'Sin consentimiento comercial registrado')+'</span>':'')+'</td><td><button data-work="restore-record" data-type="'+esc(r.type)+'" data-id="'+esc(r.id)+'" data-version="'+r.version+'">Restaurar al tablero</button></td></tr>').join('')):'<div class="w-empty"><h3>No hay registros en Históricos.</h3><p>El tacho retira registros del tablero y permite recuperarlos desde acá.</p></div>')+'</section>';}
 const archiveLabels={clients:'Cliente',policies:'Póliza',claims:'Siniestro',tasks:'Tarea',quotes:'Expediente de cotización',offers:'Propuesta',emission:'Formulario / caso de emisión',quoteIntakes:'Pedido de cotización'};
 function archiveForm(type,id,record){if(window.TuriEmission?.hasUnsavedChanges())throw Error('Guardá el borrador de emisión antes de enviarlo a Históricos.');const r=record||byId(type,id);if(!r||r.archive)return;const label=r.label||r.name||r.number||r.title||(typeof r.risk==='string'?r.risk:'')||r.description||'Registro';modal('Enviar a Históricos', '<form id="work-archive" class="w-form" data-type="'+esc(type)+'" data-id="'+esc(id)+'" data-version="'+r.version+'"><p class="w-span"><b>'+esc(label)+'</b><br>Se retirará de la lista y los indicadores. Su copia se conserva en Históricos y podés restaurarla. Los registros y documentos vinculados se conservan por separado.</p>'+(type==='policies'?'<p class="w-span">Esta acción no da de baja la póliza en la compañía.</p>':type==='emission'?'<p class="w-span">Mientras esté archivado, su enlace de cliente estará pausado. Restaurarlo permite volver a usar el enlace hasta su vencimiento original.</p>':'')+notes('','Nota del archivo (opcional)','note',1500)+'<div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="close">Cancelar</button><button class="primary" type="submit">Enviar a Históricos</button></div></form>');}
 async function restoreRecord(type,id,version){await ctx.request('/work/archive/'+type+'/'+encodeURIComponent(id),'POST',{action:'restore',expectedVersion:version});notice='Registro restaurado. Volvió al tablero con su información original.';await reload();render();}
 function moneyInput(label,value){return input(label,'amount',value,'text','inputmode="decimal" required maxlength="80" aria-label="'+esc(label)+'" aria-describedby="amount-preview"').replace('</label>','<small class="w-money-help" id="amount-preview" role="status">Acepta coma o punto y cifras pegadas desde una planilla.</small></label>');}
 function updateMoneyPreview(){const f=document.querySelector('.w-dialog input[name="amount"]'),p=document.querySelector('#amount-preview');if(!f||!p)return;try{p.textContent=f.value.trim()?'Se guardará: '+money(window.TuriAmounts.parseCents(f.value),document.querySelector('.w-dialog [name=currency]')?.value||'ARS'):'Acepta coma o punto y cifras pegadas desde una planilla.';p.classList.remove('error');}catch(e){p.textContent=e.message;p.classList.add('error');}}
 function endorsementRow(e={}){return '<fieldset class="w-endorsement" data-endorsement-row><legend>Endoso</legend><div class="w-form">'+[['Referencia / número','reference',120],['Fecha','date',10],['Tipo de endoso','type',120]].map(([label,key,max])=>'<label>'+label+'<input data-endorsement-field="'+key+'" type="'+(key==='date'?'date':'text')+'" maxlength="'+max+'" value="'+esc(e[key]||'')+'"></label>').join('')+'<label class="w-span">Detalle<textarea data-endorsement-field="detail" maxlength="2000" rows="2">'+esc(e.detail||'')+'</textarea></label><button type="button" data-work="remove-endorsement">Quitar este endoso del borrador</button></div></fieldset>';}
 function policyExtraFields(r){return '<section class="w-policy-section w-span"><div class="row between"><h3>Endosos</h3><button type="button" data-work="add-endorsement">＋ Agregar endoso</button></div><p>Registrá el número, la fecha y el cambio informado por la compañía.</p><div id="policy-endorsements">'+(r?.endorsements||[]).map(endorsementRow).join('')+'</div></section><details class="w-policy-section w-span" id="policy-cancellation" '+(r?.status==='cancelled'||r?.cancelledOn?'open':'')+'><summary>Baja: fecha y motivo</summary><p>Registro interno. El trámite y su confirmación corresponden a la compañía. Para una baja nueva, completá fecha y motivo.</p><div class="w-form">'+input('Fecha de baja','cancelledOn',r?.cancelledOn,'date')+notes(r?.cancellationReason,'Motivo de baja','cancellationReason',1500)+'</div></details>';}
 document.addEventListener('input',e=>{if(e.target.matches('.w-dialog [name=amount]'))updateMoneyPreview();});
 document.addEventListener('change',e=>{if(e.target.matches('.w-dialog [name=currency]'))updateMoneyPreview();if(e.target.matches('#work-record[data-type=policies] [name=status]')&&e.target.value==='cancelled'){const section=document.querySelector('#policy-cancellation');section.open=true;section.scrollIntoView?.({block:'nearest',behavior:'smooth'});}});

 function clientsPage(){const data=rows('clients');return `<section class="panel w-list-panel">${data.length?table(['Cliente','Contacto','Origen','Estado',''],data.map(c=>`<tr><td><div class="w-record-title"><b>${esc(c.name)}</b>${archiveButton('clients',c,c.name)}</div>${rowOwner(c)}</td><td>${c.phone?`<a href="https://wa.me/${esc(c.phone.replace(/\D/g,''))}" target="_blank" rel="noopener noreferrer">${esc(c.phone)} ↗</a>`:''}${c.email?`<span class="w-subtle">${esc(c.email)}</span>`:''}${!c.email&&!c.phone?'<span class="small">Contacto pendiente</span>':''}</td><td>${esc(c.source)}<span class="w-subtle">${c.marketingConsent?'Acepta comunicaciones comerciales':'Sin consentimiento comercial'}</span></td><td>${pill(c.archived?'Archivado':'En cartera',c.archived?'neutral':'good')}</td><td><div class="row">${btn('Abrir','edit',`data-type="clients" data-id="${c.id}"`)}${btn('Formulario de emisión','client-case',`data-id="${c.id}"`)}${btn('Documentos'+(store.documentSummary?.counts.find(x=>x.client_id===c.id)?.count?' ('+store.documentSummary.counts.find(x=>x.client_id===c.id).count+')':''),'documents',`data-type="clients" data-id="${c.id}"`)}</div></td></tr>`).join('')):empty('Cada cliente tiene su lugar.','Cargá el primero para vincular sus pólizas, solicitudes y tareas.','clients','Nuevo cliente')}</section>`}
 function policiesPage(){const data=rows('policies');return `<section class="panel w-list-panel">${data.length?table(['Cliente y póliza','Riesgo','Compañía','Vigencia','Estado',''],data.map(p=>`<tr><td><b>${esc(clientName(p.client_id))}</b><div class="w-record-title"><span class="w-subtle">${esc(p.number)}</span>${archiveButton('policies',p,p.number)}</div>${rowOwner(p)}</td><td>${esc(p.risk)}<span class="w-subtle">${esc(p.branch)} · ${money(p.premiumCents,p.currency)}</span></td><td>${esc(company(p.company_id))}</td><td>${date(p.starts_on)}<br>${date(p.expires_on)}${['active','renewal'].includes(p.status)&&days(p.expires_on)<=7?`<br>${pill(days(p.expires_on)<0?'Revisar vencimiento':'Próxima a vencer','warn')}`:''}</td><td>${status(p.status)}<span class="w-subtle">Pago: ${esc(labels[p.paymentStatus])}</span></td><td><div class="row">${btn('Abrir','edit',`data-type="policies" data-id="${p.id}"`)}${btn('Documentos','documents',`data-type="policies" data-id="${p.id}"`)}</div></td></tr>`).join('')):empty('Tu cartera, sin planillas sueltas.','Registrá pólizas existentes con su cliente, compañía y vencimiento.','policies','Registrar póliza')}</section>`}
 function claimsPage(){const data=rows('claims');return `<section class="panel w-list-panel">${data.length?table(['Caso','Póliza','Próximo paso','Estado',''],data.map(c=>`<tr><td><div class="w-record-title"><b>${esc(c.title)}</b>${archiveButton('claims',c,c.title)}</div><span class="w-subtle">${esc(c.reference||'Sin número de expediente')} · ${date(c.occurred_on)}</span>${rowOwner(c)}</td><td>${esc(policyName(c.policy_id))}</td><td>${esc(c.nextAction||'Definir próximo paso')}<span class="w-subtle">${date(c.next_due)}</span></td><td>${status(c.status)}</td><td><div class="row">${btn('Abrir','edit',`data-type="claims" data-id="${c.id}"`)}${btn('Documentos','documents',`data-type="claims" data-id="${c.id}"`)}</div></td></tr>`).join('')):empty('Un próximo paso para cada siniestro.','Abrí un expediente vinculado a una póliza para hacer el seguimiento.','claims','Abrir siniestro')}</section>`}
 function quotesPage(){const data=rows('quotes'),intakes=(store.quoteIntakes||[]).filter(owns).filter(q=>!search||[q.description,...Object.values(q.risk||{}),clientName(q.clientId)].join(' ').toLowerCase().includes(search.toLowerCase()));return `<section class="panel"><div class="w-card-title"><div><h2>Pedí una cotización con lo que tengas.</h2><p>No necesitás conocer todos los datos ni tener al cliente cargado.</p></div>${btn('Cotizar con Turi','nav','data-page="multiquote"',true)}</div>${intakes.length?table(['Pedido inicial','Cliente','Estado',''],intakes.map(q=>`<tr><td><b>${esc([q.risk?.brand,q.risk?.model,q.risk?.year].filter(Boolean).join(' ')||'Pedido inicial de auto')}</b><span class="w-subtle">${esc(q.description||q.risk?.locality||'Datos por completar')}</span>${rowOwner(q)}</td><td>${q.clientId?esc(clientName(q.clientId)):'Lo vinculás después'}</td><td>${pill(q.status==='needs_data'?'Datos por completar':'Conexión pendiente','warn')}<span class="w-subtle">Orientación inicial · no es oferta</span></td><td>${btn('Retomar pedido','quote-continue',`data-id="${q.id}"`)}${archiveButton('quoteIntakes',q,q.description||'Pedido de cotización')}</td></tr>`).join('')):'<p class="small">Tus pedidos iniciales aparecerán acá para retomarlos cuando tengas más información.</p>'}</section><div class="w-inline-note">Expedientes y propuestas recibidas: registrá las respuestas de las compañías y compará sus condiciones. Las consultas automáticas a aseguradoras todavía requieren habilitación. ${btn('Registrar expediente existente','new','data-type="quotes"')}</div><section class="panel w-list-panel">${data.length?table(['Solicitud','Cliente','Propuestas','Estado',''],data.map(q=>`<tr><td><div class="w-record-title"><b>${esc(q.risk)}</b>${archiveButton('quotes',q,q.risk)}</div><span class="w-subtle">${esc(q.branch)}</span>${rowOwner(q)}</td><td>${esc(clientName(q.client_id))}</td><td>${store.offers.filter(o=>o.quote_id===q.id).length} registradas</td><td>${status(q.status)}</td><td>${btn('Ver expediente','quote-detail',`data-id="${q.id}"`)}</td></tr>`).join('')):empty('Una solicitud, toda la información.','También podés registrar un expediente con propuestas que ya recibiste.','quotes','Registrar expediente')}</section>`}
 function tasksPage(){const data=rows('tasks').sort((a,b)=>(a.status==='done')-(b.status==='done')||a.due_on.localeCompare(b.due_on));return `<section class="panel w-list-panel">${data.length?table(['Prioridad','Gestión','Vencimiento','Estado',''],data.map(t=>`<tr><td>${pill(labels[t.priority],t.priority==='red'?'danger':t.priority==='amber'?'warn':'good')}</td><td><div class="w-record-title"><b>${esc(t.title)}</b>${archiveButton('tasks',t,t.title)}</div><span class="w-subtle">${esc(labels[t.category])}${t.client_id?' · '+esc(clientName(t.client_id)):''}</span>${rowOwner(t)}</td><td>${date(t.due_on)}${t.status==='open'&&days(t.due_on)<0?'<br>'+pill('Vencida','danger'):''}</td><td>${status(t.status)}</td><td><div class="row">${btn('Abrir','edit',`data-type="tasks" data-id="${t.id}"`)}${t.status==='open'?btn('Resolver','done',`data-id="${t.id}"`):''}</div></td></tr>`).join('')):empty('Que no quede nada suelto.','Creá tareas de renovación, pagos, siniestros, contabilidad o ventas.','tasks','Nueva tarea')}</section>`}
 function companiesPage(){const data=integrations.filter(r=>(!owner||r.producer_id===owner)&&(!search||[company(r.company_id),name(r.producer_id)].join(' ').toLowerCase().includes(search.toLowerCase())));return `<div class="w-inline-note">Guardar el código PAS prepara la integración. Podés guardar tus 15 códigos PAS. Para operar con una compañía desde Turi hacen falta además credenciales API, permisos y una prueba de concordancia de cartera. El código PAS por sí solo no habilita transacciones.</div><div class="w-company-grid">${data.map(c=>{const insurer=ctx.companies.find(x=>x.id===c.company_id);return `<section class="panel w-company-card connection"><div class="w-company-heading"><h2>${esc(company(c.company_id))}</h2>${pill('Código resguardado','good')}</div><p class="small">${esc(name(c.producer_id))} · código versión ${c.code_version}</p><div class="w-integration-steps"><div><span>Permiso</span>${status(c.stale?'pending':c.permission||'pending')}</div><div><span>Canal</span>${pill(labels[c.channel]||'Gestión asistida')}</div><div><span>Validación técnica</span>${pill(c.stale?'Revisar versión nueva':labels[c.technical]||'Pendiente','warn')}</div><div><span>Cotización automática</span>${pill('No habilitada')}</div></div><div class="row">${btn('Relevar integración','integration',`data-id="${c.id}"`)}<span class="small">${esc(insurer.api?.label||"Canal API por relevar")} · gestión dentro de Turi</span></div>${!admin()?`<div class="row mt"><button data-action="edit" data-id="${c.id}">Reemplazar código</button><button data-action="delete" data-id="${c.id}">Quitar</button></div>`:''}</section>`}).join('')}</div>${!data.length?`<section class="panel">${empty('Acá empieza la conexión. ',admin()?'Las compañías aparecerán cuando cada productor registre sus códigos desde su cuenta.':'Agregá tus compañías y tu código PAS propio. Luego relevaremos cada acceso.')}<div class="row">${!admin()?'<button data-action="add" class="primary">Agregar compañía</button>':btn('Ver productores','nav','data-page="producers"')}</div></section>`:''}<section class="panel mt"><h2>Las primeras dos compañías.</h2><p>Para el primer cotizador elegiremos un ramo y dos compañías con acceso verificable. Podés registrar documentación, permisos y lo que falta desde cada ficha.</p><p class="small">Un código PAS no inicia sesión en el portal ni habilita una API. Las transacciones con la compañía se habilitarán aquí cuando el acceso esté validado.</p></section>`}
 function producersPage(){if(!adminData)return '';return `<div class="w-stats"><div class="w-stat"><span>Productores activados</span><strong>${adminData.users.filter(u=>u.role==='producer').length}</strong></div><div class="w-stat"><span>Compañías registradas</span><strong>${integrations.length}</strong></div><div class="w-stat"><span>Accesos con código confirmado</span><strong>${adminData.users.filter(u=>u.code_configured).length}</strong></div><div class="w-stat"><span>Conectores automáticos</span><strong>0</strong></div></div><section class="panel w-list-panel">${table(['Cuenta','Acceso','Cartera','Compañías',''],adminData.users.map(u=>`<tr><td><b>${esc(u.name)}</b><span class="w-subtle">${esc(u.username)} · ${u.role==='superadmin'?'Superadministrador':'Productor'}</span></td><td>${status(u.code_configured?'confirmed':'pending')}</td><td>${store.clients.filter(c=>c.owner_id===u.id&&!c.archived).length} clientes<br>${store.policies.filter(p=>p.owner_id===u.id).length} pólizas</td><td>${integrations.filter(c=>c.producer_id===u.id).length} / 15</td><td><div class="row">${btn('Ver cartera','owner',`data-id="${u.id}"`)}${u.id!==ctx.user.id?`<button data-action="revoke" data-id="${u.id}">Cerrar sesiones</button>`:''}</div></td></tr>`).join(''))}</section><section class="panel"><h2>Invitaciones a productores</h2><p class="small">Cada productor elige sus credenciales. El enlace se muestra una sola vez al crearlo.</p>${(adminData.invitations||[]).length?table(['Productor','Estado',''],adminData.invitations.map(i=>`<tr><td>${esc(i.name)}<span class="w-subtle">Vence ${new Date(i.expires_at).toLocaleDateString('es-AR')}</span></td><td>${pill(i.used_at?'Cuenta creada':i.revoked_at?'Revocada':i.expires_at<Date.now()?'Vencida':'Pendiente',i.used_at?'good':'neutral')}</td><td>${!i.used_at&&!i.revoked_at&&i.expires_at>Date.now()?btn('Revocar invitación','revoke-invite',`data-id="${i.id}"`):''}</td></tr>`).join('')):'<p class="small">No hay invitaciones registradas.</p>'}</section><p class="small">Sólo aparecen cuentas activadas. Cada productor carga sus códigos desde su propia cuenta; el administrador supervisa sin leerlos.</p>`}
 function activityPage(){const events=store.events||[];return `<section class="panel w-list-panel">${events.length?table(['Momento','Cuenta','Movimiento','Registro'],events.map(a=>`<tr><td>${new Date(a.created_at).toLocaleString('es-AR')}</td><td>${esc(name(a.actor_id))}</td><td>${esc(actionName(a.action))}</td><td><code>${esc(a.record_id||'—')}</code></td></tr>`).join('')):empty('Los movimientos van a aparecer acá.','Cada cambio guarda la cuenta responsable y el momento.')}</section>`}
 function actionName(s){const known={'auth.login':'Ingreso a la cuenta','auth.activated':'Cuenta activada','auth.personal_code_set':'Código personal confirmado','connection.created':'Código PAS registrado','connection.replaced':'Código PAS reemplazado','connection.deleted':'Código PAS eliminado','work.integration.reviewed':'Integración relevada','work.quotes.approved_for_processing':'Revisión del PAS aprobada','admin.sessions_revoked':'Sesiones cerradas','admin.producer_created':'PAS de prueba creado'};if(known[s])return known[s];if(s.startsWith('document.'))return ({uploaded:'Archivo guardado',downloaded:'Archivo original recuperado',previewed:'Foto consultada',archived:'Archivo movido a papelera',restored:'Archivo restaurado',updated:'Datos del archivo actualizados'})[s.split('.')[1]]||s;const m=s.match(/^work\.(\w+)\.(created|updated)$/);return m?`${{clients:'Cliente',policies:'Póliza',claims:'Siniestro',tasks:'Tarea',quotes:'Solicitud',offers:'Propuesta'}[m[1]]||m[1]} ${m[2]==='created'?'registrado/a':'actualizado/a'}`:s}
 async function reload(){const results=await Promise.all([ctx.request('/work/overview'),ctx.request('/work/integrations'),admin()?ctx.request('/admin/overview'):Promise.resolve(null),ctx.request('/audit'),ctx.request('/documents/summary')]);store={...results[0],events:results[3].events};integrations=results[1].integrations;adminData=results[2];store.documentSummary=results[4];window.TuriNotifications?.configure({...ctx,openCase:async item=>{if(document.querySelector('#w-dialog-slot dialog[open]'))throw Error('Guardá o cerrá el formulario abierto antes de entrar al caso.');if(window.TuriEmission?.hasUnsavedChanges())throw Error('Guardá el borrador de emisión antes de abrir otra respuesta.');await window.TuriEmission.open(item.caseId,item.responseId);page='emission';search='';notice='Respuesta recibida. Recuperá sus datos y revisalos antes de incorporarlos.';render();ctx.root.querySelector('h1')?.focus({preventScroll:true});window.scrollTo?.(0,0);return true;}});window.TuriEmission?.configure({...ctx,clients:store.clients,owners:store.owners,integrations,quotes:store.quotes,offers:store.offers,changed:async()=>{await reload();render()}});if(page==='emission')await window.TuriEmission?.load();window.TuriMultiQuote?.configure({...ctx,clients:store.clients,owners:store.owners,changed:async()=>{await reload();render()}});if(page==='multiquote')await window.TuriMultiQuote?.load();if(!admin())owner=ctx.user.id;window.TuriDocuments?.configure({...ctx,clients:store.clients,policies:store.policies,claims:store.claims,owners:store.owners,changed:async()=>{await reload();render()}});if(page==='documents')await window.TuriDocuments?.load();if(page==='archive')store.archiveRecords=(await ctx.request('/work/archive')).records;}
 async function open(options){if(ctx?.user.id!==options.user.id){page='home';owner='';search='';notice='';}ctx=options;window.TuriMultiQuote?.configure(ctx);const found=new URLSearchParams(location.hash.slice(1)).get('view');if(found&&Object.hasOwn(titles,found)&&!(found==='producers'&&!admin()))page=found;else if(page==='producers'&&!admin())page='home';await reload();render()}
 async function go(dest){if(!Object.hasOwn(titles,dest)||(dest==='producers'&&!admin()))return;page=dest;search='';notice='';if(page==='documents')await window.TuriDocuments?.load();if(page==='multiquote')await window.TuriMultiQuote?.load();if(page==='emission')await window.TuriEmission?.load();if(page==='archive')store.archiveRecords=(await ctx.request('/work/archive')).records;history.replaceState(null,'',location.pathname+'#view='+page);render();ctx.root.querySelector('h1')?.focus({preventScroll:true});window.scrollTo?.(0,0)}
 function input(label,key,value='',type='text',extra=''){return `<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`}
 function select(label,key,values,value='',extra=''){return `<label>${label}<select name="${key}" ${extra}>${values.map(v=>{const [id,title]=Array.isArray(v)?v:[v,labels[v]||v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(title)}</option>`}).join('')}</select></label>`}
 function notes(value='',label='Notas para el seguimiento',key='notes',max=3000){return `<label class="w-span">${label}<textarea name="${key}" maxlength="${max}" rows="3">${esc(value)}</textarea></label>`}
 const allowedOwners=()=>store.owners.filter(o=>!o.disabled);
 const ownerField=(r)=>admin()?select('Cuenta responsable','ownerId',allowedOwners().map(o=>[o.id,o.name+(o.id===ctx.user.id?' · mi espacio':'')]),r?.owner_id||owner||ctx.user.id,r?'disabled':'required'):`<input type="hidden" name="ownerId" value="${esc(ctx.user.id)}">`;
 function recordForm(type,id){const r=id?byId(type,id):null;if(id&&(!r||r.archive))return;const initialOwner=r?.owner_id||owner||ctx.user.id;let fields='';
  const related=(kind,label,key,value,required=true)=>select(label,key,[["",required?'Seleccioná un registro':'Sin cliente vinculado'],...store[kind].filter(v=>v.owner_id===initialOwner&&(!v.archive||v.id===value)&&(kind!=='clients'||!v.archived||v.id===value)).map(v=>[v.id,kind==='clients'?v.name:`${v.number} · ${clientName(v.client_id)}`])],value||'',`data-related="${kind}" ${required?'required':''}`);
  if(type==='clients')fields=input('Nombre y apellido / razón social','name',r?.name,'text','required maxlength="160"')+input('Correo electrónico','email',r?.email,'email','maxlength="320"')+input('Teléfono (incluí país y área)','phone',r?.phone,'tel','maxlength="40" placeholder="+54 9 11…"')+input('Origen de la consulta','source',r?.source||'Carga manual','text','maxlength="100"')+notes(r?.notes)+`<label class="check w-span"><input type="checkbox" name="marketingConsent" ${r?.marketingConsent?'checked':''}><span>El cliente dio su consentimiento para comunicaciones comerciales.</span></label>`+(r?.archived?'<label class="check w-span"><input type="checkbox" name="archived" checked><span>Archivo anterior: desmarcá para volver a cartera. Para retirar el registro de la lista usá el tacho.</span></label>':'');
  if(type==='policies')fields=related('clients','Cliente','clientId',r?.client_id)+select('Compañía','companyId',[["",'Seleccioná una compañía'],...ctx.companies.map(c=>[c.id,c.name])],r?.company_id,'required')+input('Número de póliza','number',r?.number,'text','required maxlength="120"')+select('Ramo','branch',branches,r?.branch||'Autos')+input('Bien / actividad asegurada','risk',r?.risk,'text','required maxlength="300"')+select('Estado administrativo','status',['active','renewal','cancelled','expired'],r?.status||'active')+input('Inicio de vigencia','startsOn',r?.starts_on||store.today,'date','required')+input('Fin de vigencia','expiresOn',r?.expires_on,'date','required')+moneyInput('Importe registrado',r?.amountText||(r?window.TuriAmounts.input(r.premiumCents):''))+select('Moneda','currency',['ARS','USD'],r?.currency||'ARS')+input('Tipo de cobertura','coverageType',r?.coverageType,'text','maxlength="160" list="policy-coverage-types" placeholder="Ej.: Terceros completo + granizo"')+'<datalist id="policy-coverage-types"><option value="Responsabilidad civil"><option value="Terceros completo"><option value="Terceros completo + granizo y cristales"><option value="Todo riesgo"><option value="Incendio y robo"><option value="Otra cobertura"></datalist>'+select('Forma de pago','paymentMethod',[['unknown','Por confirmar'],['cbu','Débito por CBU'],['card','Débito en tarjeta'],['coupon','Cuponera'],['cash','Efectivo'],['transfer','Transferencia'],['other','Otra']],r?.paymentMethod||'unknown')+input('Localidad','locality',r?.locality,'text','maxlength="160"')+input('Provincia','province',r?.province,'text','maxlength="100"')+select('Tipo de refacturación','rebilling',[['unknown','Por confirmar'],['monthly','Mensual'],['bimonthly','Bimestral'],['quarterly','Trimestral'],['four_monthly','Cuatrimestral'],['semiannual','Semestral'],['annual','Anual'],['other','Otra']],r?.rebilling||'unknown')+input('Detalle de refacturación','rebillingDetails',r?.rebillingDetails,'text','maxlength="300" placeholder="Opcional"')+select('Situación del pago','paymentStatus',['unknown','current','pending'],r?.paymentStatus||'unknown')+input('Referencia de la forma de pago','paymentDetails',r?.paymentDetails,'text','maxlength="600" placeholder="Referencia o indicaciones del medio elegido"')+notes(r?.coverage,'Detalle de cobertura registrado','coverage',1200)+policyExtraFields(r)+notes(r?.notes);
  if(type==='claims')fields=related('policies','Póliza vinculada','policyId',r?.policy_id)+input('N.º de siniestro en compañía (opcional)','reference',r?.reference,'text','maxlength="120"')+input('Descripción breve','title',r?.title,'text','required maxlength="200"')+input('Fecha del hecho','occurredOn',r?.occurred_on||store.today,'date',`required max="${store.today}"`)+select('Estado','status',['reported','documents','insurer','resolved'],r?.status||'reported')+input('Próximo seguimiento','nextDue',r?.next_due,'date')+notes(r?.nextAction,'Próxima acción','nextAction',600)+notes(r?.notes);
  if(type==='tasks')fields=input('¿Qué hay que resolver?','title',r?.title,'text','required maxlength="200"')+select('Área','category',['renewals','updates','requotes','cancellations','claims','payments','accounting','marketing','other'],r?.category||'other')+input('Fecha límite','dueOn',r?.due_on||store.today,'date','required')+select('Prioridad','priority',['red','amber','green'],r?.priority||'amber')+select('Estado','status',['open','done'],r?.status||'open')+related('clients','Cliente (opcional)','clientId',r?.client_id,false)+notes(r?.notes);
  if(type==='quotes')fields=related('clients','Cliente','clientId',r?.client_id)+select('Ramo','branch',branches,r?.branch||'Autos')+input('Bien / actividad a cotizar','risk',r?.risk,'text','required maxlength="400"')+select('Estado del pedido','status',['draft','requested','comparing','approval','rejected'],r?.status||'draft')+notes(r?.notes,'Datos del riesgo y requisitos');
  const singular={clients:'cliente',policies:'póliza',claims:'siniestro',tasks:'tarea',quotes:'solicitud'}[type];
  modal(`${r?'Editar':'Registrar'} ${singular}`,`<form id="work-record" class="w-form" data-type="${type}" data-id="${r?.id||''}" data-version="${r?.version||''}">${ownerField(r)}${fields}<div class="w-form-hint w-span">${type==='policies'?'Registrar o editar esta ficha no emite ni modifica una póliza en la compañía.':type==='quotes'?'Esta solicitud prepara la gestión. Los importes se cargan desde propuestas verificables.':'Se guarda en tu cuenta privada y se conserva la atribución del productor.'}</div><div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="close">Cancelar</button><button class="primary" type="submit">Guardar ${singular}</button></div></form>`);
 }
 function modal(title,html){document.querySelector('#w-dialog-slot').innerHTML=`<dialog class="w-dialog" aria-labelledby="work-dialog-title"><div class="w-dialog-header"><div><div class="eyebrow">TURI GESTIÓN</div><h2 id="work-dialog-title">${esc(title)}</h2></div><button data-work="close" aria-label="Cerrar">${icon('close')}</button></div>${html}</dialog>`;const d=document.querySelector('.w-dialog');if(d.showModal)d.showModal();else d.setAttribute('open','');d.addEventListener('close',()=>d.remove());d.querySelector('input:not([type="hidden"]),select,button')?.focus();updateMoneyPreview();}
 function close(){pendingProducer=null;const d=document.querySelector('.w-dialog');if(d){if(d.close)d.close();d.remove()}}
 function integrationForm(id){const c=integrations.find(r=>r.id===id);if(!c)return;modal('Relevar '+company(c.company_id),`<form id="work-integration" class="w-form" data-id="${c.id}" data-version="${c.version||''}" data-code-version="${c.code_version}"><p class="w-span">Productor: ${esc(name(c.producer_id))}. Código versión ${c.code_version}. Este relevamiento no activa la cotización automática.</p>${select('Permiso de integración','permission',['pending','confirmed','blocked'],c.stale?'pending':c.permission||'pending')}${select('Canal previsto','channel',['assisted','api_requested'],c.channel||'assisted')}${select('Avance técnico','technical',['pending','documentation','testing'],c.stale?'pending':c.technical||'pending')}${input('Documentación oficial (enlace HTTPS)','documentation',c.documentation,'url','maxlength="1500"')}${notes(c.notes,'Qué tenemos, qué falta y próximo contacto')}<div class="w-form-hint w-span">No pegues códigos PAS, contraseñas, tokens ni claves en estas notas. Las credenciales se gestionan desde la cuenta del productor.</div><div id="dialog-error" class="error w-span" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="close">Cancelar</button><button class="primary" type="submit">Guardar relevamiento</button></div></form>`)}
 function quoteDetail(id){const q=byId('quotes',id);if(!q)return;window.TuriQuoteExplorer.open({quote:q,offers:store.offers.filter(o=>o.quote_id===q.id),companies:ctx.companies,today:store.today,user:ctx.user,clientName:clientName(q.client_id),ownerName:name(q.owner_id),statusLabel:labels[q.status]||q.status,modal});if(q.status==='approved')document.querySelector('#q-explorer')?.insertAdjacentHTML('beforebegin',`<div class="ei-actions"><button class="primary" data-work="emission-from-quote" data-id="${esc(q.id)}">Preparar formulario de emisión</button><span class="small">Crea un caso nuevo y conserva la propuesta aprobada.</span></div>`);}
 function quoteFollowupForm(quoteId,companyId=''){const q=byId('quotes',quoteId);if(!q||['approved','rejected'].includes(q.status))return;const row=(q.companyFollowup||[]).find(r=>r.companyId===companyId);modal('Seguimiento de compañía',`<form id="work-quote-followup" class="w-form" data-quote="${q.id}" data-version="${q.version}"><p class="w-span">${esc(clientName(q.client_id))} · ${esc(q.risk)}</p>${select('Compañía','companyId',[["",'Seleccioná una compañía'],...ctx.companies.map(c=>[c.id,c.name])],companyId,'required')}${select('Respuesta registrada','responseStatus',[["pending",'Pendiente de respuesta'],["error",'Incidencia o consulta fallida'],["no_offer",'Sin propuesta para este riesgo']],row?.status||'pending','required')}${notes(row?.note||'','Detalle y próximo paso (opcional)','responseNote',600)}<p class="w-form-hint w-span">Este estado lo registra el productor. Las propuestas recibidas se cuentan desde el expediente.</p><div id="dialog-error" class="error w-span" role="alert"></div><div class="w-form-actions w-span">${btn('Volver','quote-detail',`data-id="${q.id}"`)}<button type="submit" class="primary">Guardar seguimiento</button></div></form>`);}
 function offerForm(quoteId,id){const q=byId('quotes',quoteId),r=id?byId('offers',id):null;if(!q)return;modal(r?'Editar propuesta':'Cargar propuesta de compañía',`<form id="work-offer" class="w-form" data-id="${r?.id||''}" data-version="${r?.version||''}" data-quote="${q.id}"><p class="w-span">${esc(clientName(q.client_id))} · ${esc(q.risk)}</p>${select('Compañía','companyId',ctx.companies.map(c=>[c.id,c.name]),r?.company_id||ctx.companies[0].id,'required')}${moneyInput('Importe de la propuesta',r?window.TuriAmounts.input(r.premiumCents):'')}${select('Moneda','currency',['ARS','USD'],r?.currency||'ARS')}${select('Período del importe','period',['monthly','annual','single'],r?.period||'monthly')}${input('Propuesta válida hasta','validUntil',r?.valid_until||store.today,'date','required')}${input('Fuente verificable / n.º de cotización','sourceReference',r?.sourceReference,'text','required maxlength="400" placeholder="Portal, correo y referencia de la propuesta"')}${select('Categoría de búsqueda','coverageCategory',Object.entries(window.TuriQuoteExplorer.groups),r?.coverageCategory||'unclassified')}${notes(r?.coverage,'Cobertura y condiciones originales','coverage',1500)}${notes(r?.limits,'Sumas y límites (según la propuesta)','limits',1500)}${notes(r?.deductible,'Franquicia (o indicá Sin franquicia)','deductible',600)}${notes(r?.notes,'Notas de la propuesta','notes',2000)}<div class="w-form-hint w-span">Transcribí condiciones de una propuesta recibida de la compañía. Los precios no se generan ni se consultan automáticamente. La categoría de búsqueda debe ser confirmada por el productor; no reemplaza las condiciones originales.</div><div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="quote-detail" data-id="${q.id}">Volver</button><button type="submit" class="primary">Guardar propuesta</button></div></form>`)}
 function approvalForm(quoteId,offerId){const q=byId('quotes',quoteId),o=byId('offers',offerId);if(!q||!o)return;modal('Tu revisión como productor',`<form id="work-approve" class="w-form" data-quote="${q.id}" data-offer="${o.id}" data-offer-version="${o.version}" data-version="${q.version}"><p class="w-span"><b>${esc(clientName(q.client_id))}</b><br>${esc(company(o.company_id))} · ${money(o.premiumCents,o.currency)} · ${esc(labels[o.period])}<br>${esc(o.coverage)}</p><label class="check w-span"><input name="confirmed" type="checkbox" required><span>Revisé los datos del cliente, el riesgo y las condiciones de esta propuesta. Autorizo continuar la gestión en la compañía con mi código PAS.</span></label><p class="w-form-hint w-span">Aprobar esta revisión no emite cobertura. La póliza legal y la confirmación deben provenir de la aseguradora.</p><div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="quote-detail" data-id="${q.id}">Volver</button><button class="primary" type="submit">Registrar mi aprobación</button></div></form>`)}

 function inviteProducerForm(){if(!admin())return;modal('Invitar a un PAS',`<form id="work-invite" class="w-form"><p class="w-span">El productor elige su usuario y contraseña desde un enlace personal. Su cartera empieza vacía.</p>${input('Nombre del productor','name','','text','required maxlength="120"')}<div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="close">Cancelar</button><button type="submit" class="primary">Crear invitación</button></div></form>`);}
 function producerInvited(r){modal('Invitación preparada',`<p>Para ${esc(r.name)}. El enlace sirve una sola vez y vence el ${new Date(r.expiresAt).toLocaleDateString('es-AR')}.</p><p>Compartilo de forma privada con el productor para que cree sus credenciales.</p><label>Enlace personal<input id="pas-invite-link" readonly value="${esc(r.activationUrl)}"></label><p><button data-work="copy-invite-link">Copiar invitación</button></p><p class="small" id="pas-invite-copy-status" role="status"></p><button data-work="close">Cerrar</button>`);}

 function producerForm(){if(!admin())return;modal('Crear un PAS de prueba',`<form id="work-producer" class="w-form" autocomplete="on"><p class="w-span">Elegí el usuario y la contraseña que vas a usar para probar el MVP como productor regular.</p>${input('Nombre visible','name','PAS de prueba · Mauro','text','required maxlength="120"')}${input('Usuario del PAS','username','pas-prueba-mauro','text','required minlength="3" maxlength="40" autocomplete="username" autocapitalize="none" spellcheck="false"')}${input('Contraseña del PAS','password','','password','required minlength="14" maxlength="128" autocomplete="new-password"')}${input('Repetí la contraseña','passwordConfirmation','','password','required minlength="14" maxlength="128" autocomplete="new-password"')}<p class="w-form-hint w-span">Usá una frase de al menos 14 caracteres. Al crear la cuenta verás su código personal para guardar.</p><div class="error w-span" id="dialog-error" role="alert"></div><div class="w-form-actions w-span"><button type="button" data-work="close">Cancelar</button><button type="submit" class="primary">Crear PAS de prueba</button></div></form>`);}
function producerCreated(result,password){modal('Tu PAS de prueba está creado',`<p>Usuario: <strong>${esc(result.user.username)}</strong></p><p>Guardá este código personal junto con la contraseña que elegiste. Se muestra una sola vez.</p><code class="secret" id="created-pas-code">${esc(result.accessCode)}</code><p><button type="button" data-work="copy-pas-code">Copiar código personal</button></p><p class="small" id="pas-code-status" aria-live="polite">El PAS tiene los mismos permisos que un productor regular.</p><div id="dialog-error" class="error" role="alert"></div><div class="row"><button type="button" data-work="close">Seguir como Super Admin</button><button type="button" class="primary" data-work="pas-enter">Guardé el código. Entrar como PAS</button></div>`);pendingProducer={username:result.user.username,password,code:result.accessCode};}
 function issue(e){const dest=document.querySelector('#dialog-error')||document.querySelector('#error');if(dest)dest.textContent=e.message;if(e.status===401){close();document.body.classList.remove('in-workspace');ctx.expired(e)}}
 async function done(id){const t=byId('tasks',id);if(!t)return;await ctx.request('/work/tasks/'+id,'POST',{...t,ownerId:t.owner_id,expectedVersion:t.version,clientId:t.client_id,dueOn:t.due_on,status:'done'});notice='Tarea resuelta. El movimiento quedó registrado.';await reload();render()}
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-work]');if(!el||!ctx)return;try{switch(el.dataset.work){case'nav':await go(el.dataset.page);break;case'new-producer':producerForm();break;case'invite-producer':inviteProducerForm();break;case'revoke-invite':await ctx.request('/admin/invitations/'+encodeURIComponent(el.dataset.id)+'/revoke','POST',{});await reload();render();break;case'copy-invite-link':{const field=document.querySelector('#pas-invite-link');try{await navigator.clipboard.writeText(field.value);document.querySelector('#pas-invite-copy-status').textContent='Invitación copiada.'}catch{field.focus();field.select();document.querySelector('#pas-invite-copy-status').textContent='Enlace seleccionado. Copialo para compartirlo.'}break;}case'copy-pas-code':{const code=document.querySelector('#created-pas-code'),status=document.querySelector('#pas-code-status');try{await navigator.clipboard.writeText(code.textContent);status.textContent='Código copiado. Guardalo junto con tu usuario y contraseña.';}catch{const range=document.createRange();range.selectNodeContents(code);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);status.textContent='Código seleccionado. Copialo y guardalo antes de entrar.';}break;}case'pas-enter':{if(!pendingProducer||busy)return;busy=true;el.disabled=true;const d=await ctx.request('/auth/login','POST',pendingProducer);close();await ctx.enterAccount(d);break;}case'owner':owner=el.dataset.id;await go('policies');break;case'new':recordForm(el.dataset.type);break;case'edit':recordForm(el.dataset.type,el.dataset.id);break;case'documents':{const type=el.dataset.type,r=byId(type,el.dataset.id);if(r){const scope={ownerId:r.owner_id,clientId:type==='clients'?r.id:type==='policies'?r.client_id:byId('policies',r.policy_id)?.client_id,policyId:type==='clients'?'':type==='policies'?r.id:r.policy_id,claimId:type==='claims'?r.id:''};await window.TuriDocuments.browse(scope);await go('documents');}break;}case'close':close();break;case'integration':integrationForm(el.dataset.id);break;case'quote-followup':quoteFollowupForm(el.dataset.quote,el.dataset.company||'');break;case'emission-from-quote':close();await window.TuriEmission?.fromQuote(el.dataset.id);await go('emission');break;case'archive':archiveForm(el.dataset.type,el.dataset.id);break;case'restore-record':if(busy)return;busy=true;el.disabled=true;await restoreRecord(el.dataset.type,el.dataset.id,Number(el.dataset.version));break;case'add-endorsement':{const host=document.querySelector('#policy-endorsements');if(host.children.length>=100)throw Error('Podés registrar hasta 100 endosos.');host.insertAdjacentHTML('beforeend',endorsementRow());host.lastElementChild.querySelector('input')?.focus();break;}case'remove-endorsement':el.closest('[data-endorsement-row]')?.remove();break;case'client-case':await window.TuriEmission?.start({clientId:el.dataset.id});await go('emission');break;case'quote-continue':await window.TuriMultiQuote?.resume(el.dataset.id);await go('multiquote');break;case'quote-detail':quoteDetail(el.dataset.id);break;case'offer':offerForm(el.dataset.id);break;case'offer-edit':{const o=byId('offers',el.dataset.id);offerForm(o.quote_id,o.id);break}case'approve':approvalForm(el.dataset.quote,el.dataset.id);break;case'done':if(busy)return;busy=true;el.disabled=true;await done(el.dataset.id);break;case'refresh':el.disabled=true;await reload();render();break;case'dismiss':notice='';render();break}}catch(e){issue(e)}finally{busy=false;el.disabled=false}});
 document.addEventListener('change',e=>{if(!ctx)return;if(e.target.id==='work-owner'){owner=e.target.value;render()}if(e.target.name==='ownerId'){const f=e.target.closest('form');for(const s of f.querySelectorAll('[data-related]')){const type=s.dataset.related,first=s.options[0].text;const old=s.value;s.innerHTML=`<option value="">${esc(first)}</option>`+store[type].filter(v=>v.owner_id===e.target.value&&!v.archive&&(type!=='clients'||!v.archived)).map(v=>`<option value="${v.id}">${esc(type==='clients'?v.name:v.number+' · '+clientName(v.client_id))}</option>`).join('');s.value=old;}}});
 document.addEventListener('input',e=>{if(e.target.id==='work-search'){search=e.target.value;document.querySelector('#w-body').innerHTML=content()}});
 document.addEventListener('submit',async e=>{const f=e.target;if(!f.id?.startsWith('work-'))return;e.preventDefault();if(busy)return;busy=true;const submit=f.querySelector('button[type="submit"]');if(submit)submit.disabled=true;const err=f.querySelector('#dialog-error');if(err)err.textContent='';try{const b=Object.fromEntries(new FormData(f));if(f.id==='work-invite'){const r=await ctx.request('/admin/invitations','POST',{name:b.name});producerInvited(r);return;}b.expectedVersion=Number(f.dataset.version);if(f.id==='work-producer'){if(b.password!==b.passwordConfirmation)throw new Error('Las contraseñas no coinciden.');const r=await ctx.request('/admin/producers','POST',b);const password=b.password;f.reset();await reload();render();producerCreated(r,password);return;}if(f.id==='work-archive'){await ctx.request('/work/archive/'+f.dataset.type+'/'+encodeURIComponent(f.dataset.id),'POST',{action:'archive',expectedVersion:Number(f.dataset.version),note:b.note||''});close();if(f.dataset.type==='emission'){window.TuriEmission.reset();history.replaceState(null,'',location.pathname+'#view=emission');}notice='Enviado a Históricos. El registro y sus vínculos se conservan; podés restaurarlo.';await reload();render();return;}if(f.id==='work-record'){const type=f.dataset.type,r=f.dataset.id?byId(type,f.dataset.id):null;b.ownerId=r?.owner_id||b.ownerId||ctx.user.id;b.archived=f.elements.archived?!!f.elements.archived.checked:!!r?.archived;b.marketingConsent=!!f.elements.marketingConsent?.checked;if(type==='policies'){b.premiumCents=window.TuriAmounts.parseCents(b.amount);b.amountText=b.amount; b.endorsements=[...f.querySelectorAll('[data-endorsement-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-endorsement-field]')].map(input=>[input.dataset.endorsementField,input.value])));}await ctx.request('/work/'+type+(r?'/'+r.id:''),'POST',b);notice='Registro guardado. Ya está disponible en tu cuenta.';}else if(f.id==='work-integration'){await ctx.request('/work/integrations/'+f.dataset.id,'POST',{...b,codeVersion:Number(f.dataset.codeVersion)});notice='Relevamiento guardado. La integración continúa en validación.';}else if(f.id==='work-quote-followup'){const q=byId('quotes',f.dataset.quote);const companyFollowup=[...(q.companyFollowup||[]).filter(row=>row.companyId!==b.companyId),{companyId:b.companyId,status:b.responseStatus,note:b.responseNote}];await ctx.request('/work/quotes/'+q.id,'POST',{ownerId:q.owner_id,clientId:q.client_id,branch:q.branch,risk:q.risk,status:q.status,notes:q.notes||'',expectedVersion:Number(f.dataset.version),companyFollowup});notice='Seguimiento de la compañía actualizado.';}else if(f.id==='work-offer'){const q=byId('quotes',f.dataset.quote);await ctx.request('/work/offers'+(f.dataset.id?'/'+f.dataset.id:''),'POST',{...b,ownerId:q.owner_id,quoteId:q.id,premiumCents:window.TuriAmounts.parseCents(b.amount)});notice='Propuesta registrada con su fuente y condiciones.';}else if(f.id==='work-approve'){await ctx.request('/work/quotes/'+f.dataset.quote+'/approve','POST',{...b,offerId:f.dataset.offer,offerVersion:Number(f.dataset.offerVersion),confirmed:!!f.elements.confirmed.checked});notice='Revisión PAS registrada. La emisión debe confirmarse en la compañía.';}close();await reload();render();if(f.id==='work-offer'||f.id==='work-approve'||f.id==='work-quote-followup')quoteDetail(f.dataset.quote);}catch(e){issue(e);if(e.code==='VERSION'){await reload();}}finally{busy=false;if(submit)submit.disabled=false}});
 return {open,refresh:async()=>{await reload();render()},leave:()=>{close();window.TuriNotifications?.reset();window.TuriOriginalViewer?.close();window.TuriEmission?.reset();window.TuriMultiQuote?.reset();window.TuriQuoteExplorer?.reset();document.body.classList.remove('in-workspace');window.TuriDocuments?.reset()},go,archive:archiveForm};
})();
